import { cells as AUTOMATED_CELLS, playwright_versions } from '../../../results/automated.json';
import { cells as MANUAL_CELLS, devices as MANUAL_DEVICES } from '../../../results/manual.json';

/**
 * The two halves of what /compat displays, joined by cell id at build time:
 *   - results/automated.json — generated by `pnpm test` (never edit by hand):
 *     what Playwright's Chromium/Firefox/WebKit measured.
 *   - results/manual.json — hand-edited only: what a human saw on real Safari
 *     on the two devices it names.
 * Every id /compat shows must be in both files; `null` in manual.json means
 * "not device-tested" (rendered as `?`), a real value is always a device check.
 */

export type RealSafari = { pass: boolean; device: string; version: string } | null;
export type Verdict = {
	chromium: boolean;
	firefox: boolean;
	webkit: boolean;
	safariOld: RealSafari;
	safariNew: RealSafari;
};

type Device = { device: string; version: string };
type ManualCell = { old: boolean | null; new: boolean | null };
type AutomatedCell = { chromium: boolean; firefox: boolean; webkit: boolean };

/** The bundled browser versions behind the automated columns. */
export const PLAYWRIGHT_VERSIONS: Record<'chromium' | 'firefox' | 'webkit', string> =
	playwright_versions;

const automated = AUTOMATED_CELLS as Record<string, AutomatedCell | undefined>;
const manual = MANUAL_CELLS as Record<string, ManualCell | undefined>;

function realSafari(pass: boolean | null, d: Device): RealSafari {
	return pass === null ? null : { pass, device: d.device, version: d.version };
}

/**
 * Throws on a missing id in either file rather than rendering a row with a
 * silently missing half — a missing automated entry means `pnpm test` hasn't
 * been run since a test backing it was added (or the id was renamed); a
 * missing manual entry means nobody has listed it for a human to check yet.
 */
export function result(id: string): Verdict {
	const auto = automated[id];
	if (!auto) {
		throw new Error(
			`no automated result for '${id}' — run 'pnpm test' to regenerate results/automated.json`
		);
	}
	const hand = manual[id];
	if (!hand) {
		throw new Error(
			`no manual entry for '${id}' — add it to results/manual.json (null = untested)`
		);
	}
	return {
		chromium: auto.chromium,
		firefox: auto.firefox,
		webkit: auto.webkit,
		safariOld: realSafari(hand.old, MANUAL_DEVICES.old),
		safariNew: realSafari(hand.new, MANUAL_DEVICES.new)
	};
}
